const left=part('left','arduino-uno',[-60,-14],90);
part('board','breadboard',[-33,-10]);
const right=part('right','arduino-uno',[38,-14],270);
seat('dipL','dip-switch-8','board','1a','F12');
seat('dipR','dip-switch-8','board','1a','F42');
const colors=['purple','blue','turquoise','green','yellow','orange','red','gray'];
for(let i=0;i<8;i++){
 const pin=String(i+2), lcol=12+i, rcol=42+i, color=colors[i];
 const l=`board:G${lcol}`, r=`board:G${rcol}`;
 wire(`D${i}-left`,left.pin(pin),l,color,[[x(l),y(left.pin(pin))]]);
 const busL=`board:I${lcol}`, busR=`board:I${rcol}`, busY=72+i*4;
 wire(`D${i}-bus`,busL,busR,color,[[x(busL),busY],[x(busR),busY]]);
 wire(`D${i}-right`,right.pin(pin),r,color,[[x(r),y(right.pin(pin))]]);
 const gl=`board:A${lcol}`, gr=`board:A${rcol}`;
 const railL=`board:-top${8+i}`, railR=`board:-top${34+i}`;
 const gyL=-88-i*3, gyR=-88-i*3;
 wire(`G${i}-left`,gl,railL,'black',[[x(gl),gyL],[x(railL),gyL]]);
 wire(`G${i}-right`,gr,railR,'black',[[x(gr),gyR],[x(railR),gyR]]);
}
wire('left-ground',left.pin('GND.1'),'board:-top2','black',[[x('board:-top2'),y(left.pin('GND.1'))]]);
wire('right-ground',right.pin('GND.1'),'board:-top48','black',[[x('board:-top48'),y(right.pin('GND.1'))]]);
